const loadDiff = (): void => {
    if (diffBusyRef.current)
        return;
    const action = createActionDeadline();
    const generation = ++diffGenerationRef.current;
    diffControllerRef.current?.abort();
    diffControllerRef.current = action.controller;
    diffBusyRef.current = true;
    setDiffBusy(true);
    setDiffError("");
    void api.diff(event.repo_id, event.file, event.commit_hash, action.signal).then((result) => {
        if (diffGenerationRef.current !== generation || action.signal.aborted)
            return;
        setDiff(result.diff);
    }, (errorValue) => {
        if (diffGenerationRef.current !== generation)
            return;
        if (isAbortError(errorValue) && !action.didTimeout())
            return;
        const message = action.didTimeout()
            ? "Diff timed out after 10 seconds."
            : `Diff failed: ${String(errorValue).slice(0, 100)}`;
        setDiffError(message);
        onStatus?.(`${message} See the diff row for recovery.`);
    }).finally(() => {
        action.clear();
        if (diffGenerationRef.current === generation) {
            diffControllerRef.current = null;
            diffBusyRef.current = false;
            setDiffBusy(false);
        }
    });
};

const hideDiff = (): void => {
    diffGenerationRef.current += 1;
    diffControllerRef.current?.abort();
    diffControllerRef.current = null;
    diffBusyRef.current = false;
    setDiff(null);
    setDiffError("");
    setDiffBusy(false);
};

onClickCallbacks:
(clickEvent) => {
    if (diff !== null) {
        const row = diffRowRef.current;
        if (!online && document.activeElement === clickEvent.currentTarget
            && row?.isConnected && row.contains(clickEvent.currentTarget)
            && !row.closest("[inert]") && !document.body.dataset.overlayOpen) {
            row.focus({ preventScroll: true });
        }
        hideDiff();
    }
    else {
        loadDiff();
    }
}

